# Document authoring ---------------------------------------------------------
#
# RcmdrShiny can edit R Markdown and knitr documents in the Script tab.  The
# document is a plain text buffer with a light model on top: chunks, sections,
# a path and a mode (`r`, `rmd` or `rnw`).  Commands generated by the dialogs
# are appended as code chunks when a document mode is active.
#
# The helpers below are pure where possible so they can be tested without a
# Shiny session; the functions that need the application state are marked.

#' Document modes
#' @return A character vector.
#' @keywords internal
document_modes <- function() c("r", "rmd", "rnw")

#' File extension for a document mode
#' @param mode `"r"`, `"rmd"` or `"rnw"`.
#' @return A file extension without the dot.
#' @keywords internal
document_extension <- function(mode = "r") {
  switch(mode, rmd = "Rmd", rnw = "Rnw", "R")
}

#' Detect the document mode from a file name
#' @param path File name.
#' @return `"rmd"`, `"rnw"` or `"r"`.
#' @keywords internal
document_detect_mode <- function(path) {
  extension <- tolower(tools::file_ext(path))
  if (extension %in% c("rmd", "md")) {
    "rmd"
  } else if (identical(extension, "rnw")) {
    "rnw"
  } else {
    "r"
  }
}

#' Ace editor mode for a document mode
#' @keywords internal
document_ace_mode <- function(mode) {
  switch(mode, rmd = "markdown", rnw = "latex", "r")
}

document_lines <- function(text) {
  if (is.null(text) || !nzchar(text)) return(character())
  strsplit(text, "\n", fixed = TRUE)[[1L]]
}

document_join <- function(lines) {
  paste(lines, collapse = "\n")
}

document_with_trailing_newline <- function(text) {
  if (!nzchar(text)) return(text)
  if (endsWith(text, "\n")) text else paste0(text, "\n")
}

# -- state access ------------------------------------------------------------

#' The current document
#' @keywords internal
document <- function(state) {
  state$document %||% list(text = "", path = NULL, mode = "r")
}

#' @keywords internal
document_text <- function(state) document(state)$text

#' @keywords internal
document_path <- function(state) document(state)$path

#' @keywords internal
document_mode <- function(state) document(state)$mode

#' @keywords internal
document_set_text <- function(state, text) {
  current <- document(state)
  current$text <- paste(text, collapse = "\n")
  state$document <- current
  invisible(current$text)
}

#' @keywords internal
document_set_path <- function(state, path) {
  current <- document(state)
  current$path <- path
  state$document <- current
  invisible(path)
}

#' Enable the menu options that match a document mode
#' @keywords internal
document_enable_options <- function(state, mode) {
  state$options$use_markdown <- identical(mode, "rmd")
  state$options$use_knitr <- identical(mode, "rnw")
  invisible(NULL)
}

#' @keywords internal
document_set_mode <- function(state, mode) {
  if (!mode %in% document_modes()) {
    stop(sprintf("Unknown document mode: %s", mode), call. = FALSE)
  }
  current <- document(state)
  current$mode <- mode
  state$document <- current
  document_enable_options(state, mode)
  state_touch(state)
  invisible(mode)
}

# -- templates ---------------------------------------------------------------

#' New document template
#' @param mode `"rmd"` or `"rnw"`.
#' @param title Document title.
#' @return A character vector of lines.
#' @keywords internal
document_template <- function(mode = "rmd", title = "RcmdrShiny report") {
  if (identical(mode, "rmd")) {
    return(c(
      "---",
      sprintf('title: "%s"', gsub('"', '\\\\"', title)),
      sprintf('date: "%s"', Sys.Date()),
      "output: html_document",
      "---",
      "",
      "## Analysis",
      ""
    ))
  }
  if (identical(mode, "rnw")) {
    return(c(
      "\\documentclass{article}",
      "\\begin{document}",
      "",
      "\\section{Analysis}",
      "",
      "\\end{document}",
      ""
    ))
  }
  character()
}

#' Create a new document in the application state
#' @keywords internal
document_new <- function(state, mode = "rmd", title = "RcmdrShiny report") {
  document_set_text(state, document_template(mode, title))
  document_set_path(state, NULL)
  document_set_mode(state, mode)
  invisible(TRUE)
}

# -- chunks and sections -----------------------------------------------------

#' Bounds of the code chunks in a document
#'
#' @param text Document text.
#' @param mode Document mode.
#' @return A data frame with `start` and `end` line numbers (1-based).
#' @keywords internal
document_chunk_bounds <- function(text, mode = "rmd") {
  lines <- document_lines(text)
  if (length(lines) == 0L) {
    return(data.frame(start = integer(), end = integer()))
  }
  if (identical(mode, "rnw")) {
    starts <- grepl("^\\s*<<.*>>=\\s*$", lines)
    ends <- grepl("^\\s*@\\s*$", lines)
  } else {
    starts <- grepl("^\\s*```\\s*\\{", lines)
    ends <- grepl("^\\s*```\\s*$", lines)
  }
  out <- list()
  inside <- FALSE
  start <- NA_integer_
  for (i in seq_along(lines)) {
    if (!inside && starts[[i]]) {
      inside <- TRUE
      start <- i
    } else if (inside && ends[[i]]) {
      inside <- FALSE
      out[[length(out) + 1L]] <- c(start, i)
    }
  }
  if (length(out) == 0L) {
    return(data.frame(start = integer(), end = integer()))
  }
  data.frame(
    start = vapply(out, `[[`, integer(1), 1L),
    end = vapply(out, `[[`, integer(1), 2L)
  )
}

#' Lines inside chunks
#' @keywords internal
document_chunk_lines <- function(text, mode = "rmd") {
  lines <- document_lines(text)
  bounds <- document_chunk_bounds(text, mode)
  if (nrow(bounds) == 0L) return(rep(FALSE, length(lines)))
  inside <- rep(FALSE, length(lines))
  for (i in seq_len(nrow(bounds))) {
    inside[seq.int(bounds$start[[i]], bounds$end[[i]])] <- TRUE
  }
  inside
}

#' Line numbers of section headings outside chunks
#' @keywords internal
document_section_lines <- function(text, mode = "rmd") {
  lines <- document_lines(text)
  if (length(lines) == 0L) return(integer())
  inside <- document_chunk_lines(text, mode)
  if (identical(mode, "rnw")) {
    heading <- grepl("^\\s*\\\\(section|subsection|subsubsection)\\*?\\{", lines)
  } else {
    heading <- grepl("^#{1,6}\\s+\\S", lines)
  }
  which(!inside & heading)
}

#' Append a block, keeping a blank line between blocks
#' @keywords internal
document_append_block <- function(text, block) {
  prefix <- if (!nzchar(text)) {
    ""
  } else if (endsWith(text, "\n\n")) {
    ""
  } else if (endsWith(text, "\n")) {
    "\n"
  } else {
    "\n\n"
  }
  paste0(text, prefix, block, "\n")
}

#' Append a code chunk
#' @keywords internal
document_append_chunk <- function(state, code, mode = document_mode(state),
                                  label = "", options = character()) {
  code <- paste(code, collapse = "\n")
  if (!nzchar(trimws(code))) return(invisible(NULL))
  header <- paste(c(if (nzchar(label)) label else character(), options),
                  collapse = ", ")
  block <- if (identical(mode, "rnw")) {
    paste0("<<", header, ">>=\n", code, "\n@")
  } else {
    paste0("```{r", if (nzchar(header)) paste0(" ", header) else "",
           "}\n", code, "\n```")
  }
  text <- document_text(state)
  if (identical(mode, "rnw") && grepl("\\\\end\\{document\\}", text)) {
    position <- regexpr("\\\\end\\{document\\}", text)
    before <- substr(text, 1L, position - 1L)
    after <- substr(text, position, nchar(text))
    separator <- if (!nzchar(before) || endsWith(before, "\n")) "" else "\n"
    text <- paste0(before, separator, block, "\n\n", after)
  } else {
    text <- document_append_block(text, block)
  }
  document_set_text(state, text)
  invisible(text)
}

#' Append a section heading
#' @keywords internal
document_append_section <- function(state, title, level = 2L,
                                    mode = document_mode(state)) {
  title <- trimws(title)
  if (!nzchar(title)) stop("The section title is required.", call. = FALSE)
  level <- max(1L, min(6L, as.integer(level)))
  heading <- if (identical(mode, "rnw")) {
    command <- switch(as.character(level),
                      "1" = "section", "2" = "subsection",
                      "3" = "subsubsection", "subsubsection")
    sprintf("\\%s{%s}", command, title)
  } else {
    paste0(strrep("#", level), " ", title)
  }
  text <- document_append_block(document_text(state), heading)
  document_set_text(state, text)
  invisible(text)
}

#' Remove the last code chunk
#' @keywords internal
document_remove_last_chunk <- function(state, mode = document_mode(state)) {
  text <- document_text(state)
  lines <- document_lines(text)
  bounds <- document_chunk_bounds(text, mode)
  if (nrow(bounds) == 0L) {
    return(invisible(FALSE))
  }
  last <- bounds[nrow(bounds), ]
  drop <- seq.int(last$start, last$end)
  # Remove one blank line before the block as well.
  if (last$start > 1L && !nzchar(trimws(lines[[last$start - 1L]]))) {
    drop <- c(last$start - 1L, drop)
  }
  document_set_text(state, document_join(lines[-drop]))
  invisible(TRUE)
}

#' Remove the last section heading
#' @keywords internal
document_remove_last_section <- function(state, mode = document_mode(state)) {
  text <- document_text(state)
  lines <- document_lines(text)
  sections <- document_section_lines(text, mode)
  if (length(sections) == 0L) {
    return(invisible(FALSE))
  }
  drop <- max(sections)
  if (drop < length(lines) && !nzchar(trimws(lines[[drop + 1L]]))) {
    drop <- c(drop, drop + 1L)
  }
  document_set_text(state, document_join(lines[-drop]))
  invisible(TRUE)
}

#' Code chunks as a plain script
#' @keywords internal
document_script_from_chunks <- function(text, mode = "rmd") {
  lines <- document_lines(text)
  bounds <- document_chunk_bounds(text, mode)
  if (nrow(bounds) == 0L) return("")
  chunks <- vapply(seq_len(nrow(bounds)), function(i) {
    from <- bounds$start[[i]] + 1L
    to <- bounds$end[[i]] - 1L
    if (to < from) "" else paste(lines[seq.int(from, to)], collapse = "\n")
  }, character(1))
  paste(chunks[nzchar(trimws(chunks))], collapse = "\n\n")
}

#' Chunk that contains a given line
#'
#' @param text Document text.
#' @param row Zero-based line number, as reported by Ace.
#' @param mode Document mode.
#' @return The chunk code, or `""`.
#' @keywords internal
document_chunk_at <- function(text, row, mode = "rmd") {
  bounds <- document_chunk_bounds(text, mode)
  if (nrow(bounds) == 0L) return("")
  line <- as.integer(row) + 1L
  hit <- which(bounds$start <= line & bounds$end >= line)
  if (length(hit) == 0L) return("")
  chunk <- bounds[hit[[1L]], ]
  lines <- document_lines(text)
  from <- chunk$start + 1L
  to <- chunk$end - 1L
  if (to < from) "" else paste(lines[seq.int(from, to)], collapse = "\n")
}

#' Wrap a plain script in a document
#' @keywords internal
document_wrap_script <- function(script, mode = "rmd",
                                 title = "RcmdrShiny report") {
  text <- document_join(document_template(mode, title))
  block <- if (identical(mode, "rnw")) {
    paste0("<<>>=\n", script, "\n@")
  } else {
    paste0("```{r}\n", script, "\n```")
  }
  document_append_block(text, block)
}

# -- mode switching ----------------------------------------------------------

#' Switch the document mode without losing code
#'
#' R -> Rmd/Rnw wraps the script in a chunk.  Rmd/Rnw -> R extracts the chunk
#' code.  Rmd <-> Rnw converts the chunk markers and keeps the prose.
#'
#' @keywords internal
document_switch_mode <- function(state, mode) {
  if (!mode %in% document_modes()) {
    stop(sprintf("Unknown document mode: %s", mode), call. = FALSE)
  }
  current <- document_mode(state)
  if (identical(current, mode)) {
    document_enable_options(state, mode)
    return(invisible(FALSE))
  }
  text <- document_text(state)

  if (identical(mode, "r")) {
    if (current %in% c("rmd", "rnw")) {
      text <- document_script_from_chunks(text, current)
    }
  } else if (identical(current, "r")) {
    text <- if (nzchar(trimws(text))) {
      document_wrap_script(text, mode)
    } else {
      document_join(document_template(mode))
    }
  } else {
    # rmd <-> rnw: the markup languages are different, so keep the code and
    # use the target template; prose is not converted.
    script <- document_script_from_chunks(text, current)
    state$document <- list(
      text = document_join(document_template(mode)),
      path = document_path(state),
      mode = mode
    )
    if (nzchar(trimws(script))) document_append_chunk(state, script, mode)
    document_set_mode(state, mode)
    return(invisible(TRUE))
  }

  document_set_text(state, text)
  document_set_mode(state, mode)
  invisible(TRUE)
}

# -- knitting ----------------------------------------------------------------

#' Availability of a knit format
#' @param format `"html"`, `"pdf"` or `"word"`.
#' @param mode Document mode.
#' @return `TRUE` or `FALSE`.
#' @keywords internal
document_format_available <- function(format = "html", mode = "rmd") {
  has_pandoc <- tryCatch(
    requireNamespace("rmarkdown", quietly = TRUE) &&
      rmarkdown::pandoc_available(),
    error = function(e) FALSE
  )
  has_latex <- nzchar(Sys.which("pdflatex"))
  if (identical(mode, "rnw")) {
    return(identical(format, "pdf") &&
             requireNamespace("knitr", quietly = TRUE) && has_latex)
  }
  if (identical(format, "html")) {
    return(has_pandoc && requireNamespace("knitr", quietly = TRUE))
  }
  if (identical(format, "pdf")) {
    return(has_pandoc && has_latex)
  }
  if (identical(format, "word")) {
    return(has_pandoc)
  }
  FALSE
}

#' Knit the current document
#'
#' Renders the document in the session environment, so the report sees the
#' active data set and models.  The output is copied to the session knit
#' directory, which the application serves for the preview tab.
#'
#' @param state Application state.
#' @param format `"html"`, `"pdf"` or `"word"`.
#' @return A list with `file`, `url`, `format` and `input`.
#' @export
document_knit <- function(state, format = "html") {
  mode <- document_mode(state)
  if (identical(mode, "r")) {
    stop("Switch to an R Markdown or knitr document first.", call. = FALSE)
  }
  text <- document_text(state)
  if (!nzchar(trimws(text))) {
    stop("The document is empty.", call. = FALSE)
  }
  format <- match.arg(format, c("html", "pdf", "word"))
  if (!document_format_available(format, mode)) {
    stop(sprintf("The '%s' format is not available: install the required tools.",
                 format), call. = FALSE)
  }

  directory <- state$knit_dir
  if (is.null(directory) || !nzchar(directory)) {
    directory <- tempfile("rcmdrshiny-knit-")
  }
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)

  extension <- if (identical(mode, "rnw")) ".Rnw" else ".Rmd"
  input <- file.path(directory, paste0("document", extension))
  writeLines(text, input, useBytes = TRUE)

  if (identical(mode, "rnw")) {
    tex <- knitr::knit(input, output = sub("\\.Rnw$", ".tex", input),
                       quiet = TRUE, envir = state$env)
    old <- setwd(dirname(tex))
    on.exit(setwd(old), add = TRUE)
    tools::texi2pdf(basename(tex), clean = TRUE, quiet = TRUE)
    output <- file.path(dirname(tex), sub("\\.tex$", ".pdf", basename(tex)))
  } else {
    output_format <- switch(
      format,
      html = rmarkdown::html_document(),
      pdf = rmarkdown::pdf_document(),
      word = rmarkdown::word_document()
    )
    output <- rmarkdown::render(
      input, output_format = output_format, output_dir = directory,
      envir = state$env, quiet = TRUE
    )
  }

  if (!file.exists(output)) {
    stop("The document was not produced. Check the Messages tab.", call. = FALSE)
  }

  url <- NULL
  prefix <- state$knit_prefix
  if (!is.null(prefix) && nzchar(prefix) &&
      normalizePath(dirname(output)) == normalizePath(directory)) {
    url <- paste0(prefix, "/", basename(output))
  }

  result <- list(
    file = output,
    url = url,
    format = if (identical(mode, "rnw")) "pdf" else format,
    input = input,
    mode = mode,
    time = Sys.time()
  )
  state$knit_result <- result
  state_touch(state)
  invisible(result)
}

#' Save the current document to disk
#' @keywords internal
document_save <- function(state, path = document_path(state)) {
  if (is.null(path) || !nzchar(path)) {
    stop("Choose a file name first.", call. = FALSE)
  }
  writeLines(document_text(state), path, useBytes = TRUE)
  document_set_path(state, path)
  state_touch(state)
  invisible(path)
}

#' Set the bibliography in the YAML front matter
#' @keywords internal
document_set_bibliography <- function(state, path) {
  if (is.null(path) || !nzchar(path)) {
    stop("Choose a bibliography file.", call. = FALSE)
  }
  entry <- sprintf('bibliography: "%s"', gsub('"', '\\\\"', path))
  lines <- document_lines(document_text(state))
  if (length(lines) > 0L && identical(trimws(lines[[1L]]), "---")) {
    closing <- which(trimws(lines) == "---")
    closing <- closing[closing > 1L]
    if (length(closing) > 0L) {
      end <- closing[[1L]]
      front <- lines[seq_len(end - 1L)]
      front <- front[!grepl("^\\s*bibliography\\s*:", front)]
      lines <- c(front, entry, lines[end:length(lines)])
    } else {
      lines <- c("---", entry, "---", "", lines)
    }
  } else {
    lines <- c(
      "---",
      'title: "RcmdrShiny report"',
      sprintf('date: "%s"', Sys.Date()),
      "output: html_document",
      entry,
      "---",
      "",
      lines
    )
  }
  document_set_text(state, document_join(lines))
  invisible(TRUE)
}

#' Open a document from disk
#' @keywords internal
document_open <- function(state, path) {
  if (!file.exists(path)) {
    stop(sprintf("File not found: %s", path), call. = FALSE)
  }
  text <- readLines(path, warn = FALSE, encoding = "UTF-8")
  mode <- document_detect_mode(path)
  document_set_text(state, paste(text, collapse = "\n"))
  document_set_path(state, path)
  document_set_mode(state, mode)
  if (!identical(mode, "r")) document_enable_options(state, mode)
  invisible(text)
}
